'use strict';

const fs = require('fs');
const input = fs.readFileSync(0, 'utf8').trim().split(/\s+/).map(Number);

const n = input[0];
const sticks = input.slice(1).sort((a, b) => a - b);

let count = 0;

for (let k = 2; k < n; k++) {
  let left = 0;
  let right = k - 1;

  while (left < right) {
    if (sticks[left] + sticks[right] > sticks[k]) {
      count += right - left;
      right--;
    } else {
      left++;
    }
  }
}

console.log(count);
